<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Orders\Application\CreateProductionFromDemand;use App\Modules\Orders\Application\Data\CreateProductionFromDemandData;use App\Modules\Orders\Presentation\Http\Requests\CreateProductionFromDemandRequest;use App\Modules\Production\Domain\Enums\LaborMethod;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Carbon;
class CreateProductionFromDemandController extends Controller {public function __invoke(CreateProductionFromDemandRequest $request,CreateProductionFromDemand $action):RedirectResponse{$d=$request->validated();$production=$action->execute(new CreateProductionFromDemandData($d['demand_ids'],Carbon::parse($d['planned_for']),isset($d['flour_quantity'])?(string)$d['flour_quantity']:null,LaborMethod::from($d['labor_method']),$d['responsible_person_id'],$request->user()));return to_route('production.show',$production)->with('success','Producción sugerida creada y pedidos vinculados.');}}
